// The evaluation schemes, one row per (scheme, stored fit): the
// degree and stored count the fit uses, and the bound each scheme is
// held to on it against the 60-digit reference, in each multiply-add
// route. scheme 0 = split Clenshaw, 1 = Horner; lane 0 = region A
// (kCoeffs), 1 = region B (kBcoeffs), 2 = the extended band
// (kExtendedBcoeffs). Each bound is the worst error a sweep over the
// fit's own interval reached, rounded up to the next power of two, so
// it is a bound and not the sweep's reading.
struct SchemeRow {
    int scheme, lane, region, deg, stored;
    double fused, separate;
};

